<?php
namespace App\Http\Controllers;
use App\Models\{Product,StockAdjustment,StockCount,StockLocation,StockTransfer};use App\Services\AdvancedInventoryService;use Illuminate\Http\Request;use Illuminate\Validation\Rule;
class InventoryOperationController extends Controller
{public function index(Request $r){$c=$r->user()->company_id;return view('inventory-operations.index',['transfers'=>StockTransfer::with(['fromLocation','toLocation'])->where('company_id',$c)->latest()->limit(10)->get(),'adjustments'=>StockAdjustment::with('location')->where('company_id',$c)->latest()->limit(10)->get(),'counts'=>StockCount::with('location')->where('company_id',$c)->latest()->limit(10)->get()]);}private function data(Request $r):array{$c=$r->user()->company_id;return ['locations'=>StockLocation::where('company_id',$c)->where('is_active',1)->get(),'products'=>Product::where('company_id',$c)->where('is_active',1)->orderBy('name')->get()];}public function transferForm(Request $r){return view('inventory-operations.transfer',$this->data($r));}public function transfer(Request $r,AdvancedInventoryService $s){$c=$r->user()->company_id;$data=$r->validate(['from_location_id'=>['required',Rule::exists('stock_locations','id')->where(fn($q)=>$q->where('company_id',$c))],'to_location_id'=>['required',Rule::exists('stock_locations','id')->where(fn($q)=>$q->where('company_id',$c))],'notes'=>'nullable|string|max:1000','items'=>'required|array','items.*.product_id'=>['required',Rule::exists('products','id')->where(fn($q)=>$q->where('company_id',$c))],'items.*.quantity'=>'nullable|numeric|min:0']);$s->transfer($data,$r->user());return redirect()->route('inventory-operations.index')->with('success','Stock transfer posted.');}public function adjustmentForm(Request $r){return view('inventory-operations.adjustment',$this->data($r));}public function adjustment(Request $r,AdvancedInventoryService $s){$c=$r->user()->company_id;$data=$r->validate(['stock_location_id'=>['required',Rule::exists('stock_locations','id')->where(fn($q)=>$q->where('company_id',$c))],'adjustment_type'=>'required|in:correction,damaged,opening','reason'=>'required|string|max:1000','items'=>'required|array','items.*.product_id'=>['required',Rule::exists('products','id')->where(fn($q)=>$q->where('company_id',$c))],'items.*.quantity_change'=>'nullable|numeric']);$s->adjust($data,$r->user());return redirect()->route('inventory-operations.index')->with('success','Stock adjustment and accounting entry posted.');}public function countForm(Request $r){return view('inventory-operations.count-start',$this->data($r));}public function startCount(Request $r,AdvancedInventoryService $s){$c=$r->user()->company_id;$data=$r->validate(['stock_location_id'=>['required',Rule::exists('stock_locations','id')->where(fn($q)=>$q->where('company_id',$c))],'notes'=>'nullable|string|max:1000']);$count=$s->startCount($data['stock_location_id'],$data['notes']??null,$r->user());return redirect()->route('inventory-operations.count.edit',$count);}public function editCount(Request $r,$count){$count=StockCount::with(['location','items.product'])->where('company_id',$r->user()->company_id)->findOrFail($count);return view('inventory-operations.count',compact('count'));}public function postCount(Request $r,$count,AdvancedInventoryService $s){$count=StockCount::where('company_id',$r->user()->company_id)->findOrFail($count);$data=$r->validate(['items'=>'required|array','items.*'=>'required|numeric|min:0']);$s->postCount($count,$data['items'],$r->user());return redirect()->route('inventory-operations.index')->with('success','Stock count posted and variances reconciled.');}}
